try{var data=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText(@"C:\Users\Stormtrooper\Git\EVOLVE - Frame\output\revit\openings_manifest.json"));var existing=new FilteredElementCollector(document).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().Where(e=>e.Category.Id.Value==(long)BuiltInCategory.OST_Windows||e.Category.Id.Value==(long)BuiltInCategory.OST_Doors).Select(e=>e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString()).ToHashSet();var made=new List<object>();
using(var tx=new Transaction(document,"A11 hosted windows and doors")){tx.Start();var levels=new FilteredElementCollector(document).OfClass(typeof(Level)).Cast<Level>().ToList();var walls=new FilteredElementCollector(document).OfClass(typeof(Wall)).Cast<Wall>().ToDictionary(w=>w.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString());var symbols=new FilteredElementCollector(document).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().Where(s=>s.FamilyName.StartsWith("LC ")).ToList();
foreach(var row in data.Where(r=>!existing.Contains((string)r["mark"])).Take(12)){
 var wall=walls[(string)row["wall"]];var point=new XYZ((double)row["x"]/304.8,(double)row["y"]/304.8,(double)row["sill"]/304.8);var cut=new FilteredElementCollector(document).OfClass(typeof(Opening)).Cast<Opening>().Where(o=>o.Host!=null&&o.Host.Id==wall.Id).OrderBy(o=>((o.BoundaryRect[0]+o.BoundaryRect[1])/2-point).GetLength()).FirstOrDefault();
 if(cut==null)throw new Exception("No provisional cut for "+(string)row["mark"]);document.Delete(cut.Id);document.Regenerate();
 var s=symbols.Single(s=>s.FamilyName==(string)row["family"]);if(!s.IsActive){s.Activate();document.Regenerate();}var level=levels.Single(l=>l.Id==wall.LevelId);var e=document.Create.NewFamilyInstance(point,s,wall,level,Autodesk.Revit.DB.Structure.StructuralType.NonStructural);e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).Set((string)row["mark"]);e.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set((string)row["note"]);var sill=e.get_Parameter(BuiltInParameter.INSTANCE_SILL_HEIGHT_PARAM);if(sill!=null&&!sill.IsReadOnly)sill.Set(point.Z-level.Elevation);document.Regenerate();var box=e.get_BoundingBox(null);made.Add(new{mark=(string)row["mark"],id=e.Id.Value,zmin=box.Min.Z*304.8,zmax=box.Max.Z*304.8});
}tx.Commit();}document.Save();return new{created=made,warnings=document.GetWarnings().Select(w=>w.GetDescriptionText()).ToArray()};}catch(Exception ex){return new{failure=ex.ToString()};}

